   568→export default function SizeCharts() {
   569→  const { charts, plan, templates, categories, canCreate } =
   570→    useLoaderData<typeof loader>();
   571→  const fetcher = useFetcher<typeof action>();
   572→  const shopify = useAppBridge();
   573→
   574→  const [showTemplates, setShowTemplates] = useState(false);
   575→  const [showImport, setShowImport] = useState(false);
   576→  const [importName, setImportName] = useState("Imported Size Chart");
   577→  const [importCategory, setImportCategory] = useState("general");
   578→  const [importCsvText, setImportCsvText] = useState("");
   579→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
   580→  const [categoryFilter, setCategoryFilter] = useState("all");
   581→  const [searchQuery, setSearchQuery] = useState("");
   582→
   583→  const isLoading = fetcher.state !== "idle";
   584→
   585→  useEffect(() => {
   586→    if (!fetcher.data) return;
   587→    const data = fetcher.data as ActionData;
   588→    if ("ok" in data && data.ok) {
   589→      shopify.toast.show(data.message);
   590→      if ("redirectId" in data && data.redirectId) {
   591→        window.location.href = `/app/size-charts/${data.redirectId}`;
   592→      } else {
   593→        setShowTemplates(false);
   594→        setShowImport(false);
   595→        setImportCsvText("");
   596→        setImportName("Imported Size Chart");
   597→      }
   598→    } else if ("error" in data) {
   599→      shopify.toast.show(data.error, { isError: true });
   600→    }
   601→  }, [fetcher.data, shopify]);
   602→
   603→  const filteredCharts = charts.filter((chart) => {
   604→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
   605→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
   606→    const matchesSearch =
   607→      searchQuery.trim() === "" ||
   608→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
   609→    return matchesStatus && matchesCategory && matchesSearch;
   610→  });
   611→
   612→  const publishedCount = charts.filter((c) => c.status === "active").length;
   613→  const draftCount = charts.filter((c) => c.status === "draft").length;
   614→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
   615→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
   616→  const maxCharts = plan.limits.maxCharts;
   617→  const isFreePlan = plan.id === "free";
   618→
   619→  const progressPct =
   620→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
   621→  const progressColor =
   622→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
   623→
   624→  function clearFilters() {
   625→    setStatusFilter("all");
   626→    setCategoryFilter("all");
   627→    setSearchQuery("");
   628→  }
   629→
   630→  return (
