   641→            ? "Cancel"
   642→            : "Create chart"
   643→          : `Limit reached (${plan.limits.maxCharts})`}
   644→      </s-button>
   645→
   646→      <s-button
   647→        slot="secondary-action"
   648→        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
   649→      >
   650→        Import CSV
   651→      </s-button>
   652→
   653→      {/* Subtitle */}
   654→      <s-text tone="neutral">
   655→        Manage your size charts and assign them to products
   656→      </s-text>
   657→
   658→      {/* ================================================================ */}
   659→      {/* PLAN LIMIT BANNER                                                 */}
   660→      {/* ================================================================ */}
   661→      {!canCreate && (
   662→        <s-section>
   663→          <div
   664→            style={{
   665→              ...cardStyle,
   666→              background: "#fff8ec",
   667→              border: "1px solid #ffd79d",
   668→              display: "flex",
   669→              alignItems: "center",
   670→              justifyContent: "space-between",
   671→              gap: "16px",
   672→            }}
   673→          >
   674→            <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
   675→              <span style={{ fontSize: "20px", flexShrink: 0, marginTop: "1px" }}>
   676→                ⚠️
   677→              </span>
   678→              <div>
   679→                <p
