   682→                    fontSize: "14px",
   683→                    fontWeight: 600,
   684→                    color: "#202223",
   685→                  }}
   686→                >
   687→                  Chart limit reached
   688→                </p>
   689→                <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
   690→                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
