   692→                  hidden fees.
   693→                </p>
   694→              </div>
   695→            </div>
   696→            <s-button href="/app/pricing" variant="primary">
   697→              Upgrade plan
   698→            </s-button>
   699→          </div>
   700→        </s-section>
   701→      )}
   702→
   703→      {/* ================================================================ */}
   704→      {/* TEMPLATE PICKER                                                   */}
   705→      {/* ================================================================ */}
   706→      {showTemplates && (
   707→        <TemplatePicker
   708→          templates={templates}
   709→          categories={categories}
   710→          isLoading={isLoading}
   711→          onClose={() => setShowTemplates(false)}
   712→          fetcher={fetcher}
   713→        />
   714→      )}
   715→
   716→      {/* ================================================================ */}
   717→      {/* CSV IMPORT PANEL                                                  */}
   718→      {/* ================================================================ */}
   719→      {showImport && (
   720→        <s-section>
   721→          <div style={cardStyle}>
   722→            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "20px" }}>
   723→              <div>
   724→                <p style={sectionTitle}>Import Size Chart from CSV</p>
   725→                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
   726→                  Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
   727→                </p>
   728→              </div>
   729→              <button
   730→                onClick={() => setShowImport(false)}
   731→                style={{
   732→                  background: "none",
   733→                  border: "1px solid #c9cccf",
   734→                  borderRadius: "6px",
   735→                  cursor: "pointer",
   736→                  padding: "4px 12px",
   737→                  fontSize: "13px",
   738→                  color: "#6d7175",
   739→                  lineHeight: "22px",
   740→                  flexShrink: 0,
   741→                  marginLeft: "16px",
   742→                }}
   743→              >
   744→                Close
   745→              </button>
   746→            </div>
   747→
   748→            {/* CSV format hint */}
   749→            <div
   750→              style={{
   751→                background: "#f9fafb",
   752→                border: "1px solid #e1e3e5",
   753→                borderRadius: "8px",
   754→                padding: "12px 14px",
   755→                marginBottom: "16px",
   756→              }}
   757→            >
   758→              <p style={{ margin: "0 0 6px", fontSize: "12px", fontWeight: 700, color: "#202223", textTransform: "uppercase", letterSpacing: "0.04em" }}>Expected CSV format</p>
   759→              <code style={{ fontSize: "12px", color: "#5c5f62", lineHeight: 1.7, display: "block", whiteSpace: "pre" }}>{`Size,Chest,Waist,Hips
   760→XS,32-34,24-26,34-36
   761→S,34-36,26-28,36-38
   762→M,36-38,28-30,38-40`}</code>
   763→            </div>
   764→
   765→            {/* Name + category row */}
   766→            <div style={{ display: "flex", gap: "12px", marginBottom: "14px", flexWrap: "wrap" }}>
   767→              <div style={{ flex: 2, minWidth: "180px" }}>
   768→                <label style={{ fontWeight: 600, fontSize: "13px", color: "#202223", display: "block", marginBottom: "4px" }} htmlFor="import-name">
   769→                  Chart name
   770→                </label>
   771→                <input
   772→                  id="import-name"
