import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, canCreateChart } from "../lib/plans";
import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [charts, subscription] = await Promise.all([
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      include: { assignments: true },
    }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
    name: t.name,
    category: t.category,
    gender: t.gender,
    rowCount: t.data.rows.length,
  }));
  const categories = getCategories();

  return {
    charts,
    plan,
    templates,
    categories,
    canCreate: canCreateChart(plan.id, charts.length),
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "create-from-template": {
        const templateName = formData.get("templateName") as string;
        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
        if (!template) return { error: "Template not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let name = template.name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) name = `${template.name} (${Date.now().toString(36)})`;

        const created = await db.sizeChart.create({
          data: {
            shop,
            name,
            category: template.category,
            data: JSON.stringify(template.data),
            status: "active",
          },
        });
        return { ok: true, message: `"${name}" created successfully`, redirectId: created.id };
      }

      case "create-blank": {
        const name = (formData.get("name") as string) || "Untitled Size Chart";
        const category = (formData.get("category") as string) || "general";

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let uniqueName = name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;

        const defaultData = {
          headers: ["Size", "Chest", "Waist", "Hips"],
          units: { default: "in", available: ["in", "cm"] },
          rows: [
            { Size: "S", Chest: "", Waist: "", Hips: "" },
            { Size: "M", Chest: "", Waist: "", Hips: "" },
            { Size: "L", Chest: "", Waist: "", Hips: "" },
          ],
        };

        const created = await db.sizeChart.create({
          data: {
            shop,
            name: uniqueName,
            category,
            data: JSON.stringify(defaultData),
            status: "draft",
          },
        });
        return { ok: true, message: `"${uniqueName}" created`, redirectId: created.id };
      }

      case "delete": {
        const id = formData.get("id") as string;
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return { ok: true, message: "Chart deleted" };
      }

      case "import-csv": {
        const csvRaw = formData.get("csvData") as string;
        const chartName = (formData.get("name") as string) || "Imported Size Chart";
        const category = (formData.get("category") as string) || "general";

        if (!csvRaw?.trim()) return { error: "CSV data is required" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
        }

        // Parse CSV
        const lines = csvRaw.trim().split(/\r?\n/).filter((l) => l.trim());
        if (lines.length < 2) return { error: "CSV must have a header row and at least one data row." };

        const parseRow = (line: string): string[] => {
          const result: string[] = [];
          let current = "";
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const ch = line[i];
            if (ch === '"') {
              if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
              else { inQuotes = !inQuotes; }
            } else if (ch === "," && !inQuotes) {
              result.push(current.trim());
              current = "";
            } else {
              current += ch;
            }
          }
          result.push(current.trim());
          return result;
        };

        const headers = parseRow(lines[0]);
        if (headers.length < 1) return { error: "Could not parse CSV headers." };

        const rows = lines.slice(1).map((line) => {
          const cells = parseRow(line);
          const row: Record<string, string> = {};
          headers.forEach((h, i) => { row[h] = cells[i] ?? ""; });
          return row;
        });

        const data = {
          headers,
          units: { default: "in", available: ["in", "cm"] },
          rows,
        };

        let uniqueName = chartName;
        const existingName = await db.sizeChart.findUnique({ where: { shop_name: { shop, name: chartName } } });
        if (existingName) uniqueName = `${chartName} (${Date.now().toString(36)})`;

        const created = await db.sizeChart.create({
          data: { shop, name: uniqueName, category, data: JSON.stringify(data), status: "draft" },
        });
        return { ok: true, message: `Imported "${uniqueName}"`, redirectId: created.id };
      }

      case "duplicate": {
        const sourceId = formData.get("id") as string;
        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
        if (!source) return { error: "Chart not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return { error: "Chart limit reached. Upgrade your plan." };
        }

        const newName = `${source.name} (Copy)`;
        await db.sizeChart.create({
          data: {
            shop,
            name: newName,
            type: source.type,
            category: source.category,
            data: source.data,
            status: "draft",
          },
        });
        return { ok: true, message: `Duplicated as "${newName}"` };
      }

      case "toggle-status": {
        const chartId = formData.get("id") as string;
        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
        if (!chart) return { error: "Chart not found" };

        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
        return {
          ok: true,
          message: `Chart ${newStatus === "active" ? "published" : "unpublished"}`,
        };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type ActionData =
  | { ok: true; message: string; redirectId?: string }
  | { error: string };

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const CATEGORY_LABELS: Record<string, string> = {
  tops: "Tops",
  bottoms: "Bottoms",
  dresses: "Dresses",
  shoes: "Shoes",
  kids: "Kids",
  rings: "Rings",
  sportswear: "Sportswear",
  general: "General",
};

const CATEGORY_ICONS: Record<string, string> = {
  tops: "👕",
  bottoms: "👖",
  dresses: "👗",
  shoes: "👟",
  kids: "🧒",
  rings: "💍",
  sportswear: "🏃",
  general: "📏",
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

interface TemplateSectionProps {
  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
  categories: string[];
  isLoading: boolean;
  onClose: () => void;
  fetcher: ReturnType<typeof useFetcher<typeof action>>;
}

function TemplatePicker({ templates, categories, isLoading, onClose, fetcher }: TemplateSectionProps) {
  const [hoveredCard, setHoveredCard] = useState<string | null>(null);

  const groupedTemplates = categories.reduce<Record<string, typeof templates>>((acc, cat) => {
    const group = templates.filter((t) => t.category === cat);
    if (group.length > 0) acc[cat] = group;
    return acc;
  }, {});

  return (
    <s-section>
      <div
        style={{
          background: "#ffffff",
          border: "1px solid #e3e3e3",
          borderRadius: "12px",
          padding: "20px",
        }}
      >
        {/* Picker header */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
            marginBottom: "20px",
          }}
        >
          <div>
            <p style={{ fontSize: "15px", fontWeight: 650, color: "#202223", margin: 0 }}>
              Choose a starting point
            </p>
            <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
              Pick a template with pre-filled sizing data, or start from scratch.
            </p>
          </div>
          <button
            onClick={onClose}
            aria-label="Close template picker"
            style={{
              background: "none",
              border: "1px solid #c9cccf",
              borderRadius: "6px",
              cursor: "pointer",
              padding: "4px 12px",
              fontSize: "13px",
              color: "#6d7175",
              lineHeight: "22px",
              flexShrink: 0,
              marginLeft: "16px",
            }}
          >
            Close
          </button>
        </div>

        {/* Start from scratch */}
        <div style={{ marginBottom: "24px" }}>
          <p
            style={{
              fontSize: "13px",
              fontWeight: 600,
              color: "#6d7175",
              textTransform: "uppercase",
              letterSpacing: "0.5px",
              margin: "0 0 10px",
            }}
          >
            Start from scratch
          </p>
          <div
            style={{
              display: "inline-block",
              border: `2px dashed ${hoveredCard === "__blank" ? "#005bd3" : "#c9cccf"}`,
              borderRadius: "10px",
              padding: "16px 24px",
              background: hoveredCard === "__blank" ? "#f3f7ff" : "#f9fafb",
              transition: "all 0.15s ease",
              cursor: "pointer",
              minWidth: "160px",
            }}
            onMouseEnter={() => setHoveredCard("__blank")}
            onMouseLeave={() => setHoveredCard(null)}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              <div
                style={{
                  width: "40px",
                  height: "40px",
                  borderRadius: "50%",
                  background: "#e4e5e7",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "18px",
                  flexShrink: 0,
                }}
              >
                📋
              </div>
              <div>
                <p
                  style={{
                    margin: "0 0 2px",
                    fontWeight: 600,
                    fontSize: "14px",
                    color: "#202223",
                  }}
                >
                  Blank chart
                </p>
                <p style={{ margin: 0, fontSize: "12px", color: "#6d7175" }}>
                  Build with your own columns and sizes
                </p>
              </div>
            </div>
            <fetcher.Form method="post" style={{ marginTop: "12px" }}>
              <input type="hidden" name="intent" value="create-blank" />
              <input type="hidden" name="name" value="Untitled Size Chart" />
              <input type="hidden" name="category" value="general" />
              <s-button type="submit" loading={isLoading}>
                Create blank
              </s-button>
            </fetcher.Form>
          </div>
        </div>

        {/* Templates by category */}
        <div>
          <p
            style={{
              fontSize: "13px",
              fontWeight: 600,
              color: "#6d7175",
              textTransform: "uppercase",
              letterSpacing: "0.5px",
              margin: "0 0 16px",
            }}
          >
            By category
          </p>

          <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
            {categories.map((cat) => {
              const group = groupedTemplates[cat];
              if (!group || group.length === 0) return null;

              return (
                <div key={cat}>
                  <p
                    style={{
                      fontSize: "14px",
                      fontWeight: 650,
                      color: "#202223",
                      margin: "0 0 8px",
                    }}
                  >
                    {CATEGORY_LABELS[cat] ?? cat}
                  </p>
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
                      gap: "12px",
                    }}
                  >
                    {group.map((template) => {
                      const cardKey = template.name;
                      const isHovered = hoveredCard === cardKey;
                      return (
                        <div
                          key={template.name}
                          style={{
                            background: isHovered ? "#f3f7ff" : "#fff",
                            border: `1px solid ${isHovered ? "#005bd3" : "#e3e3e3"}`,
                            borderRadius: "10px",
                            padding: "14px",
                            cursor: "pointer",
                            transition: "all 0.15s ease",
                            display: "flex",
                            flexDirection: "column",
                            alignItems: "center",
                            textAlign: "center",
                          }}
                          onMouseEnter={() => setHoveredCard(cardKey)}
                          onMouseLeave={() => setHoveredCard(null)}
                        >
                          <div
                            style={{
                              width: "40px",
                              height: "40px",
                              borderRadius: "50%",
                              background: "#f0f5ff",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "center",
                              fontSize: "20px",
                              marginBottom: "8px",
                            }}
                          >
                            {CATEGORY_ICONS[template.category] ?? "📏"}
                          </div>
                          <p
                            style={{
                              margin: "0 0 2px",
                              fontWeight: 600,
                              fontSize: "13px",
                              color: "#202223",
                              lineHeight: "1.3",
                            }}
                          >
                            {template.name}
                          </p>
                          <p
                            style={{
                              margin: "0 0 10px",
                              fontSize: "11px",
                              color: "#6d7175",
                            }}
                          >
                            {template.rowCount} sizes
                          </p>
                          <fetcher.Form method="post">
                            <input type="hidden" name="intent" value="create-from-template" />
                            <input type="hidden" name="templateName" value={template.name} />
                            <s-button variant="primary" type="submit" loading={isLoading}>
                              Use template
                            </s-button>
                          </fetcher.Form>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </s-section>
  );
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export default function SizeCharts() {
  const { charts, plan, templates, categories, canCreate } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [showTemplates, setShowTemplates] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importName, setImportName] = useState("Imported Size Chart");
  const [importCategory, setImportCategory] = useState("general");
  const [importCsvText, setImportCsvText] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (!fetcher.data) return;
    const data = fetcher.data as ActionData;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message);
      if ("redirectId" in data && data.redirectId) {
        window.location.href = `/app/size-charts/${data.redirectId}`;
      } else {
        setShowTemplates(false);
        setShowImport(false);
        setImportCsvText("");
        setImportName("Imported Size Chart");
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [fetcher.data, shopify]);

  const filteredCharts = charts.filter((chart) => {
    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
    const matchesSearch =
      searchQuery.trim() === "" ||
      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStatus && matchesCategory && matchesSearch;
  });

  const publishedCount = charts.filter((c) => c.status === "active").length;
  const draftCount = charts.filter((c) => c.status === "draft").length;
  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
  const maxCharts = plan.limits.maxCharts;
  const isFreePlan = plan.id === "free";

  const progressPct =
    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
  const progressColor =
    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";

  function clearFilters() {
    setStatusFilter("all");
    setCategoryFilter("all");
    setSearchQuery("");
  }

  return (
    <s-page heading="Size Charts">
      {/* Primary action */}
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={() => setShowTemplates(!showTemplates)}
        disabled={!canCreate || isLoading}
      >
        {canCreate
          ? showTemplates
            ? "Cancel"
            : "Create chart"
          : `Limit reached (${plan.limits.maxCharts})`}
      </s-button>

      <s-button
        slot="secondary-action"
        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
      >
        Import CSV
      </s-button>

      {/* Subtitle */}
      <s-text tone="neutral">
        Manage your size charts and assign them to products
      </s-text>

      {/* ================================================================ */}
      {/* PLAN LIMIT BANNER                                                 */}
      {/* ================================================================ */}
      {!canCreate && (
        <s-section>
          <s-banner tone="caution" heading="Chart limit reached">
            You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
            {plan.name} plan. Upgrade to Starter for unlimited charts with no
            hidden fees.{" "}
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          </s-banner>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TEMPLATE PICKER                                                   */}
      {/* ================================================================ */}
      {showTemplates && (
        <TemplatePicker
          templates={templates}
          categories={categories}
          isLoading={isLoading}
          onClose={() => setShowTemplates(false)}
          fetcher={fetcher}
        />
      )}

      {/* ================================================================ */}
      {/* CSV IMPORT PANEL                                                  */}
      {/* ================================================================ */}
      {showImport && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              {/* Header row */}
              <s-stack direction="inline" gap="base">
                <s-stack direction="block" gap="small-200">
                  <s-heading>Import Size Chart from CSV</s-heading>
                  <s-text tone="subdued">
                    Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
                  </s-text>
                </s-stack>
                <button
                  onClick={() => setShowImport(false)}
                  style={{
                    background: "none",
                    border: "1px solid #c9cccf",
                    borderRadius: "6px",
                    cursor: "pointer",
                    padding: "4px 12px",
                    fontSize: "13px",
                    color: "#6d7175",
                    lineHeight: "22px",
                    flexShrink: 0,
                    marginLeft: "16px",
                  }}
                >
                  Close
                </button>
              </s-stack>

              {/* CSV format hint */}
              <s-box padding="base" borderWidth="base" borderRadius="base">
                <s-stack direction="block" gap="small-200">
                  <s-text tone="subdued">
                    <strong>Expected CSV format</strong>
                  </s-text>
                  <code style={{ fontSize: "12px", color: "#5c5f62", lineHeight: 1.7, display: "block", whiteSpace: "pre" }}>{`Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38\nM,36-38,28-30,38-40`}</code>
                </s-stack>
              </s-box>

              {/* Name + category row */}
              <s-stack direction="inline" gap="base">
                <div style={{ flex: 2, minWidth: "180px" }}>
                  <label
                    style={{ fontWeight: 600, fontSize: "13px", color: "#202223", display: "block", marginBottom: "4px" }}
                    htmlFor="import-name"
                  >
                    Chart name
                  </label>
                  <input
                    id="import-name"
                    value={importName}
                    onChange={(e) => setImportName((e.target as HTMLInputElement).value)}
                    placeholder="e.g. Women's Tops"
                    style={{
                      width: "100%",
                      border: "1px solid #c9cccf",
                      borderRadius: "8px",
                      padding: "8px 12px",
                      fontSize: "14px",
                      color: "#202223",
                      background: "#fff",
                      boxSizing: "border-box" as const,
                      outline: "none",
                    }}
                  />
                </div>
                <div style={{ flex: 1, minWidth: "140px" }}>
                  <s-select
                    label="Category"
                    value={importCategory}
                    onChange={(e: Event) =>
                      setImportCategory((e.target as HTMLSelectElement).value)
                    }
                  >
                    <s-option value="general">General</s-option>
                    <s-option value="tops">Tops</s-option>
                    <s-option value="bottoms">Bottoms</s-option>
                    <s-option value="dresses">Dresses</s-option>
                    <s-option value="shoes">Shoes</s-option>
                    <s-option value="kids">Kids</s-option>
                    <s-option value="rings">Rings</s-option>
                    <s-option value="sportswear">Sportswear</s-option>
                  </s-select>
                </div>
              </s-stack>

              {/* CSV textarea */}
              <div>
                <label
                  style={{ fontWeight: 600, fontSize: "13px", color: "#202223", display: "block", marginBottom: "4px" }}
                  htmlFor="import-csv"
                >
                  CSV data
                </label>
                <textarea
                  id="import-csv"
                  value={importCsvText}
                  onChange={(e) => setImportCsvText((e.target as HTMLTextAreaElement).value)}
                  placeholder={`Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38`}
                  rows={8}
                  style={{
                    width: "100%",
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "10px 12px",
                    fontSize: "13px",
                    fontFamily: "monospace",
                    color: "#202223",
                    background: "#fff",
                    boxSizing: "border-box" as const,
                    outline: "none",
                    resize: "vertical",
                    lineHeight: 1.6,
                  }}
                />
              </div>

              {/* Import action */}
              <s-stack direction="inline" gap="base">
                <fetcher.Form method="post" style={{ display: "inline" }}>
                  <input type="hidden" name="intent" value="import-csv" />
                  <input type="hidden" name="name" value={importName} />
                  <input type="hidden" name="category" value={importCategory} />
                  <input type="hidden" name="csvData" value={importCsvText} />
                  <s-button variant="primary" type="submit" loading={isLoading} disabled={!importCsvText.trim()}>
                    Import chart
                  </s-button>
                </fetcher.Form>
                <s-text tone="subdued">
                  Chart will be created as a draft — review and publish when ready.
                </s-text>
              </s-stack>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* SEARCH + FILTER BAR (only when charts exist)                     */}
      {/* ================================================================ */}
      {charts.length > 0 && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              {/* Search input */}
              <s-search-field
                label=""
                placeholder="Search charts..."
                value={searchQuery}
                onChange={(e: Event) =>
                  setSearchQuery((e.target as HTMLInputElement).value)
                }
              />

              {/* Status pill tabs + Category dropdown */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: "12px",
                  flexWrap: "wrap",
                }}
              >
                {/* Status pill tabs — keep custom styling, no Polaris equivalent */}
                <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                  {(
                    [
                      { key: "all", label: `All (${charts.length})` },
                      { key: "active", label: `Active (${activeFilteredCount})` },
                      { key: "draft", label: `Draft (${draftFilteredCount})` },
                    ] as const
                  ).map((tab) => (
                    <button
                      key={tab.key}
                      onClick={() => setStatusFilter(tab.key)}
                      style={{
                        border: "1px solid",
                        borderColor: statusFilter === tab.key ? "#1a73e8" : "#c9cccf",
                        borderRadius: "20px",
                        padding: "4px 14px",
                        fontSize: "13px",
                        fontWeight: statusFilter === tab.key ? 600 : 400,
                        background: statusFilter === tab.key ? "#1a73e8" : "#fff",
                        color: statusFilter === tab.key ? "#fff" : "#6d7175",
                        cursor: "pointer",
                        transition: "all 0.15s ease",
                        lineHeight: "22px",
                      }}
                    >
                      {tab.label}
                    </button>
                  ))}
                </div>

                {/* Category select */}
                <s-select
                  label="Category"
                  value={categoryFilter}
                  onChange={(e: Event) =>
                    setCategoryFilter((e.target as HTMLSelectElement).value)
                  }
                >
                  <s-option value="all">All</s-option>
                  {categories.map((cat) => (
                    <s-option key={cat} value={cat}>
                      {CATEGORY_LABELS[cat] ?? cat}
                    </s-option>
                  ))}
                </s-select>
              </div>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* CHARTS LIST                                                       */}
      {/* ================================================================ */}
      <s-section>
        <s-box padding="base" borderWidth="base" borderRadius="base">
          {/* Section header */}
          {charts.length > 0 && (
            <s-stack direction="inline" gap="small-200">
              <s-heading>
                Size Charts
              </s-heading>
              <s-text tone="subdued">
                ({filteredCharts.length}
                {filteredCharts.length !== charts.length ? ` of ${charts.length}` : ""})
              </s-text>
            </s-stack>
          )}

          {/* Empty state — no charts at all */}
          {charts.length === 0 && (
            <s-stack direction="block" gap="base">
              <s-text>📐</s-text>
              <s-heading>Create your first size chart</s-heading>
              <s-text tone="neutral">
                Start by creating a size chart to help your customers find the right
                size. Reduce size-related returns by up to 40% — get started in under
                3 minutes using one of our pre-built templates.
              </s-text>
              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
                Create chart
              </s-button>
            </s-stack>
          )}

          {/* Empty state — filters applied but no results */}
          {charts.length > 0 && filteredCharts.length === 0 && (
            <s-stack direction="block" gap="base">
              <s-text>🔍</s-text>
              <s-heading>No charts match your filters</s-heading>
              <s-text tone="neutral">
                Try adjusting your search or filters to find what you are looking for.
              </s-text>
              <s-button onClick={clearFilters}>Clear filters</s-button>
            </s-stack>
          )}

          {/* Chart rows */}
          {filteredCharts.length > 0 && (
            <div style={{ marginTop: "8px" }}>
              {filteredCharts.map((chart, i) => (
                <div
                  key={chart.id}
                  style={{
                    padding: "14px 0",
                    borderBottom:
                      i === filteredCharts.length - 1
                        ? "none"
                        : "1px solid #f1f1f1",
                  }}
                >
                  <s-stack direction="inline" gap="base">
                    {/* Left: name + meta */}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <s-stack direction="block" gap="small-200">
                        <s-link href={`/app/size-charts/${chart.id}`}>
                          {chart.name}
                        </s-link>
                        <s-stack direction="inline" gap="small-200">
                          <s-badge tone={chart.status === "active" ? "success" : "neutral"}>
                            {chart.status === "active" ? "Active" : "Draft"}
                          </s-badge>
                          <s-badge tone="info">
                            {CATEGORY_LABELS[chart.category] ?? chart.category}
                          </s-badge>
                          <s-text tone="subdued">
                            {chart.assignments.length > 0
                              ? `${chart.assignments.length} product${chart.assignments.length !== 1 ? "s" : ""} assigned`
                              : "No assignments"}
                          </s-text>
                          <s-text tone="subdued">
                            Updated {formatDate(chart.updatedAt)}
                          </s-text>
                        </s-stack>
                      </s-stack>
                    </div>

                    {/* Right: actions */}
                    <s-stack direction="inline" gap="small-200">
                      <s-button href={`/app/size-charts/${chart.id}`} variant="tertiary">
                        Edit
                      </s-button>

                      <fetcher.Form method="post">
                        <input type="hidden" name="intent" value="toggle-status" />
                        <input type="hidden" name="id" value={chart.id} />
                        <s-button type="submit" loading={isLoading}>
                          {chart.status === "active" ? "Unpublish" : "Publish"}
                        </s-button>
                      </fetcher.Form>

                      <fetcher.Form method="post">
                        <input type="hidden" name="intent" value="duplicate" />
                        <input type="hidden" name="id" value={chart.id} />
                        <s-button type="submit" loading={isLoading}>
                          Duplicate
                        </s-button>
                      </fetcher.Form>

                      <fetcher.Form method="post">
                        <input type="hidden" name="intent" value="delete" />
                        <input type="hidden" name="id" value={chart.id} />
                        <s-button
                          type="submit"
                          variant="tertiary"
                          tone="critical"
                          loading={isLoading}
                        >
                          Delete
                        </s-button>
                      </fetcher.Form>
                    </s-stack>
                  </s-stack>
                </div>
              ))}
            </div>
          )}
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Limits                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Chart limits">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            {/* Plan badge row */}
            <s-stack direction="inline" gap="base">
              <s-badge tone={isFreePlan ? "neutral" : "success"}>
                {plan.name} Plan
              </s-badge>
              {plan.price > 0 && (
                <s-text tone="subdued">${plan.price}/mo</s-text>
              )}
            </s-stack>

            {maxCharts === -1 ? (
              <s-text tone="subdued">Unlimited charts on your plan.</s-text>
            ) : (
              <s-stack direction="block" gap="small-200">
                <s-stack direction="inline" gap="base">
                  <s-text>
                    {publishedCount} / {maxCharts} published
                  </s-text>
                  <s-text tone="subdued">{draftCount} draft</s-text>
                </s-stack>
                {/* Progress bar — keep as-is, no Polaris component available */}
                <div
                  style={{
                    height: "6px",
                    background: "#e4e5e7",
                    borderRadius: "3px",
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      height: "100%",
                      width: `${progressPct}%`,
                      background: progressColor,
                      borderRadius: "3px",
                      transition: "width 0.3s ease",
                    }}
                  />
                </div>
                <s-text tone="subdued">
                  {maxCharts - publishedCount > 0
                    ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                    : "Limit reached — upgrade for more"}
                </s-text>
                <s-button href="/app/pricing" variant="primary">
                  Upgrade for unlimited
                </s-button>
              </s-stack>
            )}
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick Tips                                                */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick tips">
        <s-unordered-list>
          <s-list-item>
            Assign charts to products or collections for automatic display in your
            storefront widget
          </s-list-item>
          <s-list-item>
            Templates include standard sizing data so you can get started fast
          </s-list-item>
          <s-list-item>
            Publish a chart to make it visible to customers on your store
          </s-list-item>
          <s-list-item>
            Add both inch and centimeter values for international shoppers
          </s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
